64	// Slick: slidesToShow 3 at desktop, 2 at <980px, 1 at <480px
65	function getSlidesPerPage(): number {
66	  if (typeof window === "undefined") return 3;
67	  if (window.innerWidth < 480) return 1;
68	  if (window.innerWidth < 980) return 2;
69	  return 3;
70	}
