72	export function BenefitsGrid() {
73	  const trackRef = useRef<HTMLDivElement>(null);
74	  const [activeDot, setActiveDot] = useState(0);
75	  const [totalDots, setTotalDots] = useState(2); // 6 cards / 3 per page = 2 dots
76	
77	  const updateDots = useCallback(() => {
78	    const perPage = getSlidesPerPage();
79	    setTotalDots(Math.ceil(BENEFITS.length / perPage));
80	  }, []);
81	
82	  const handleScroll = useCallback(() => {
83	    const el = trackRef.current;
84	    if (!el) return;
85	    const perPage = getSlidesPerPage();
86	    const dots = Math.ceil(BENEFITS.length / perPage);
87	    const scrollRatio = el.scrollLeft / (el.scrollWidth - el.clientWidth);
88	    const dot = Math.round(scrollRatio * (dots - 1));
89	    setActiveDot(dot);
90	  }, []);
91	
92	  const goToDot = useCallback((index: number) => {
93	    const el = trackRef.current;
94	    if (!el) return;
95	    const perPage = getSlidesPerPage();
96	    const dots = Math.ceil(BENEFITS.length / perPage);
97	    const scrollTarget =
98	      (el.scrollWidth - el.clientWidth) * (index / (dots - 1));
99	    el.scrollTo({ left: scrollTarget, behavior: "smooth" });
100	    setActiveDot(index);
101	  }, []);
102	
103	  useEffect(() => {
104	    updateDots();
105	    const el = trackRef.current;
106	    if (el) {
107	      el.addEventListener("scroll", handleScroll, { passive: true });
108	    }
109	    window.addEventListener("resize", updateDots);
110	    return () => {
111	      el?.removeEventListener("scroll", handleScroll);
112	      window.removeEventListener("resize", updateDots);
113	    };
114	  }, [handleScroll, updateDots]);
115	
116	  return (
117	    <section className={styles['worksSec']}>
118	      <div className={styles['containerLarge3']}>
119	        <div className={styles['benefitSubheadOut']}>
120	          <div className={styles['benefitsubott']}>
121	            <p className="paragraph text-left margin-bottom-0 small-font">
122	              <strong className={styles['faqSkyText']}>Our Benefits</strong>
123	            </p>
124	          </div>
125	        </div>
126	
127	        <h2 className={styles['heading2']}>
128	          Why Agencies Choose Boldteq <br />
129	          Over Hiring
130	        </h2>
131	
132	        <p className={styles['paragraph']}>
133	          Agencies partner with Boldteq to get a senior, white-label execution{" "}
134	          <br />
135	          team designed to support and deliver agency work.
136	        </p>
137	
138	        <div className={styles['featureGrid']} ref={trackRef}>
139	          {BENEFITS.map((benefit) => (
140	            <a key={benefit.title} href="#" className={styles['featureCard']}>
141	              <div className={styles['textWrapper']}>
142	                <div className={styles['subheadingLarge']}>
143	                  <strong>{benefit.title}</strong>
144	                </div>
145	                <p className={styles['paragraphSmall2']}>
146	                  {benefit.description}
147	                </p>
