151	                alt={benefit.imageAlt}
152	                width={benefit.imageWidth}
153	                height={benefit.imageHeight}
154	                className={styles['fullWidthImage']}
155	                sizes="(max-width: 479px) 100vw, (max-width: 767px) 50vw, (max-width: 991px) 50vw, 33vw"
156	              />
157	            </a>
158	          ))}
159	        </div>
160	
161	        {totalDots > 1 && (
162	          <ul className={styles['sliderDots']} aria-label="Benefits carousel navigation">
163	            {Array.from({ length: totalDots }).map((_, i) => (
164	              <li key={i}>
165	                <button
