167	                  onClick={() => goToDot(i)}
168	                  aria-label={`Go to slide ${i + 1}`}
169	                  aria-current={activeDot === i ? "true" : undefined}
170	                />
171	              </li>
172	            ))}
173	          </ul>
174	        )}
175	      </div>
176	    </section>
177	  );
178	}
